/* Presentation layer: existing story actions, question flow and save IDs are reused. */
for(const ch of Object.values(CHAPTERS))ch.questionCount=chapterQuestions(ch.chapterId).length;
let v2PendingArtChanged=false;
for(const r of [state.run,state.mainRun]){const p=r?.pending;if(!p)continue;const replacement=V2_CHOICE_BACKGROUND_CHANGES.find(c=>c.sceneId===p.sourceSceneId&&c.from===p.resultIllustrationId&&(!p.resultSceneId||c.resultSceneId===p.resultSceneId));if(replacement){p.resultIllustrationId=replacement.to;v2PendingArtChanged=true}}
if(v2PendingArtChanged)save();
let wrongFilter='all',wrongChapter='all',wrongConcept='all';
function v2OfficialStudy(){const questions=QUESTIONS.filter(q=>!q.retired&&!q.reviewOnly&&isVerifiedOfficialQuestion(q));return pageHeader('실제 기출','원본 시험지로 확인하는 한국사')+'<div class="tabs"><button data-study-jump="official" class="selected">실제 기출 '+questions.length+'</button><button data-study-jump="quiz">모든 문제</button><button data-nav="era">시대별 학습</button></div>'+questions.map(q=>'<article class="v2-question-row"><div class="question-row-copy"><span class="v2-source official">실제 기출</span><small>'+esc(questionSourceLabel(q))+'</small><h3>'+esc(q.sourceQuestionText||q.question)+'</h3><p>CH.'+CHAPTERS[q.chapterId].number+' · '+esc(q.historicalEvent||q.examKeywords?.slice(0,2).join(' · '))+'</p></div><img loading="lazy" src="'+esc(q.sourceQuestionImage)+'" alt="원본 문제 미리보기"><div class="question-row-actions"><button class="primary" data-practice="'+esc(q.questionId)+'">문제 풀기</button><button class="text-btn" data-story-memory="'+esc(q.questionId)+'">관련 스토리 다시 보기 ›</button></div></article>').join('')}
const verifiedOfficialBeforeV2=isVerifiedOfficialQuestion;
function v2LatestWrong(id){return (meta().wrongAnswers||[]).filter(e=>e.questionId===id).sort((a,b)=>(b.answeredAt||'').localeCompare(a.answeredAt||''))[0]}
function v2WrongTime(value){return v2LatestWrong(typeof value==='string'?value:value.questionId)?.answeredAt||''}
isVerifiedOfficialQuestion=q=>Boolean(verifiedOfficialBeforeV2(q)&&q.sourceQuestionImage);
const percentText=value=>value===null?'—':value+'%';
function overallProgress(){const order=chapterOrder();return order.length?Math.round(order.reduce((n,ch)=>n+chapterProgress(ch.chapterId),0)/order.length):0}
function v2Metrics(items){return '<div class="v2-metrics">'+items.map(([symbol,value,label])=>'<div><span class="metric-symbol" aria-hidden="true">'+symbol+'</span><strong>'+esc(value)+'</strong><small>'+esc(label)+'</small></div>').join('')+'</div>'}
function weakConcepts(){const weak=learningSummary(meta()).weak;return '<section class="v2-section"><h2>자주 틀린 개념 TOP 5</h2>'+(!weak.length?'<p class="muted">문제를 풀면 실제 오답 기록으로 약한 개념을 찾아드려요.</p>':weak.map((c,i)=>'<button class="weak-row" data-weak="'+esc(c.name)+'"><span class="rank">'+(i+1)+'</span><b>'+esc(c.name)+'</b><small>'+c.wrong+'회 오답</small><span class="weak-meter"><i style="width:'+c.accuracy+'%"></i></span><em>'+c.accuracy+'%</em></button>').join(''))+'</section>'}
function v2QuestionRow(q){const record=meta().questionRecords[q.questionId],detail=v2LatestWrong(q.questionId),scene=STORIES[q.relatedSceneId];return '<article class="v2-question-row"><div class="question-row-copy"><span class="v2-source '+(isVerifiedOfficialQuestion(q)?'official':'')+'">'+esc(questionKind(q))+'</span><small>'+esc(questionSourceLabel(q))+'</small><h3>'+esc(q.sourceQuestionText||q.question.split('\n')[0])+'</h3><p>'+esc((q.examKeywords||[]).slice(0,3).join(' · '))+'</p><small>'+((record?.attempts||0)-(record?.correctCount||0))+'회 오답'+(detail?.answeredAt&&Number.isFinite(Date.parse(detail.answeredAt))?' · '+esc(new Date(detail.answeredAt).toLocaleDateString('ko-KR')):'')+' · '+(meta().reviewedQuestionIds.includes(q.questionId)?'복습 완료':'복습 필요')+'</small></div>'+(q.sourceQuestionImage?'<img loading="lazy" src="'+esc(q.sourceQuestionImage)+'" alt="'+esc(questionSourceLabel(q))+' 문제 미리보기">':'')+'<div class="question-row-actions"><button class="primary" data-review="'+esc(q.questionId)+'">다시 풀기 · 해설</button>'+(scene?'<button class="text-btn" data-story-memory="'+esc(q.questionId)+'">관련 스토리 다시 보기 ›</button>':'')+'</div></article>'}
const homeBeforeV2=home,erasBeforeV2=eras,studyBeforeV2=study,recordsBeforeV2=records,shellBeforeV2=shell;
shell=function(content){return shellBeforeV2(content).replace('<div class="brand">살아본 한국사','<div class="brand">눈떠보니 한국사').replace('<span>시대</span>','<span>학습</span>').replace('<span>공부</span>','<span>오답노트</span>')};
home=function(){const r=mainRun(),info=mainChapter(),summary=learningSummary(meta()),wrong=meta().wrongQuestionIds.filter(id=>!meta().reviewedQuestionIds.includes(id)),scene=STORIES[r.storyId]||STORIES[info.startStoryId],heroAsset=ASSETS[scene?.illustrationId]||ASSETS['home-goryeo'],heroPortrait=PORTRAITS[['prologue','sleep','voice'].includes(r.storyId)?'player_neutral':'player_goryeo_neutral'];const recent=(meta().wrongAnswers||[]).slice().sort((a,b)=>(b.answeredAt||'').localeCompare(a.answeredAt||'')).slice(0,2).map(e=>QUESTIONS.find(q=>q.questionId===e.questionId)).filter(Boolean);return pageHeader('눈떠보니 한국사','역사를 살고, 기출로 기억하다')+'<section class="v2-resume" style="background-image:url(\''+esc(heroAsset.src)+'\')"><img class="v2-home-player" src="'+esc(heroPortrait.src)+'" alt="주인공"><div class="v2-resume-shade"><h2>눈떠보니<br>한국사</h2><div class="resume-bottom"><span>이어하기 · 고려</span><h3>CH.'+info.number+' '+esc(info.title)+'</h3><p>'+esc(info.subtitle)+'</p><div class="progress"><span style="width:'+progressFor(r)+'%"></span></div><small>현재 챕터 '+progressFor(r)+'% · 전체 '+overallProgress()+'%</small><button class="resume-play" data-action="'+(state.mainRun?'current-main':'play')+'" aria-label="'+(r.started?'이야기 이어하기':'이야기 시작하기')+'">▶</button></div></div></section><section class="v2-section"><h2>오늘의 학습</h2>'+v2Metrics([['♨',summary.streak+'일','연속 학습'],['▤',summary.todayAttempts,'오늘 푼 문제'],['◎',percentText(summary.todayAccuracy),'오늘 정답률'],['×',wrong.length,'복습할 오답']])+'</section><section class="v2-section"><div class="section-title"><h2>다시 풀어볼까요?</h2><button class="text-btn" data-nav="study">오답노트 ›</button></div><button class="v2-review-link" data-nav="study"><b>'+(wrong.length?'틀린 문제 '+wrong.length+'개':'이야기의 기억을 확인해요')+'</b><span>'+(summary.weak[0]?esc(summary.weak[0].name):'문제를 풀고 나만의 복습을 시작하세요')+' ›</span></button>'+recent.map(v2QuestionRow).join('')+'</section><section class="v2-section"><div class="section-title"><h2>나의 고려 이야기</h2><button class="text-btn" data-nav="era">전체 챕터 ›</button></div><div class="chapter-list">'+chapterOrder().slice(0,showAllChapters?undefined:3).map(ch=>chapterRow(ch.chapterId)).join('')+'</div><button class="chapter-list-toggle" data-action="toggle-chapters">'+(showAllChapters?'잠긴 챕터 접기':'앞으로의 챕터 '+(chapterOrder().length-3)+'개 보기')+'</button></section><section class="v2-section"><h2>시대별 진행 상황</h2><div class="v2-era-progress">'+ERAS.map(([name],i)=>'<div><b>'+esc(name)+'</b><span>'+(i===0?overallProgress()+'%':'준비중')+'</span><div class="progress"><span style="width:'+(i===0?overallProgress():0)+'%"></span></div></div>').join('')+'</div></section>'};
eras=function(){return pageHeader('학습하기','역사 속으로 한 걸음')+'<div class="tabs"><button class="selected" data-nav="era">시대별</button><button data-study-jump="official">기출 모드</button><button data-study-jump="timeline">테마 학습</button><button data-study-jump="cards">역사 도감</button></div><div class="v2-era-list">'+ERAS.map(([name,years],i)=>'<section class="v2-era-card '+(i?'coming':'')+'"><span>EPISODE '+String(i+1).padStart(2,'0')+'</span><h2>'+esc(name)+'</h2><p>'+esc(years)+'</p><small>'+(i?'준비중':chapterOrder().length+'개 챕터 · 진행률 '+overallProgress()+'% · 정답률 '+percentText(learningSummary(meta()).accuracy))+'</small>'+(i?'':'<button data-action="'+(state.mainRun?'current-main':'play')+'" class="era-enter" aria-label="고려 이야기 이어하기">›</button>')+'</section>').join('')+'</div><section class="v2-section"><h2>고려 · 챕터 선택</h2><p class="muted">완료 '+meta().completedChapters.length+' / '+chapterOrder().length+' · 현재 CH.'+mainChapter().number+'</p><div class="chapter-list">'+chapterOrder().map(ch=>chapterRow(ch.chapterId)).join('')+'</div>'+(mainRun().started?'<button class="text-btn restart-link" data-action="restart-episode">처음부터 다시하기</button>':'')+'</section>'};
study=function(){if(studyTab==='official')return v2OfficialStudy();if(studyTab!=='review')return studyBeforeV2();const ids=meta().wrongQuestionIds,all=ids.map(id=>QUESTIONS.find(q=>q.questionId===id)).filter(Boolean),visible=all.filter(q=>(wrongFilter!=='official'||isVerifiedOfficialQuestion(q))&&(wrongFilter!=='repeated'||(meta().questionRecords[q.questionId]?.attempts||0)-(meta().questionRecords[q.questionId]?.correctCount||0)>1)&&(wrongChapter==='all'||q.chapterId===wrongChapter)&&(wrongConcept==='all'||learningConcepts(q).includes(wrongConcept)));return pageHeader('오답노트','틀린 순간을 나의 지식으로')+'<div class="tabs v2-wrong-tabs"><button data-wrong-filter="all" class="'+(wrongFilter==='all'?'selected':'')+'">전체 '+all.length+'</button><button data-wrong-filter="official" class="'+(wrongFilter==='official'?'selected':'')+'">실제 기출 '+all.filter(isVerifiedOfficialQuestion).length+'</button><button data-wrong-filter="repeated" class="'+(wrongFilter==='repeated'?'selected':'')+'">반복 오답</button><button data-study-jump="official">기출 모드</button></div><div class="v2-filters"><label>시대 / 챕터<select data-wrong-chapter><option value="all">고려 전체</option>'+chapterOrder().map(ch=>'<option value="'+ch.chapterId+'" '+(wrongChapter===ch.chapterId?'selected':'')+'>CH.'+ch.number+' '+esc(ch.title)+'</option>').join('')+'</select></label><label>개념<select data-wrong-concept><option value="all">전체 개념</option>'+[...new Set(all.flatMap(learningConcepts))].sort((a,b)=>a.localeCompare(b,'ko')).map(name=>'<option '+(wrongConcept===name?'selected':'')+'>'+esc(name)+'</option>').join('')+'</select></label></div>'+weakConcepts()+'<section class="v2-section"><h2>'+(wrongFilter==='repeated'?'반복해서 틀린 문제':'최근 틀린 문제')+'</h2>'+(visible.length?visible.sort((a,b)=>(v2LatestWrong(b.questionId)?.answeredAt||'').localeCompare(v2LatestWrong(a.questionId)?.answeredAt||'')).map(v2QuestionRow).join(''):'<div class="empty">아직 틀린 역사가 없어요.<br><small>선택한 조건에 맞는 오답이 없습니다.</small></div>')+'</section>'};
records=function(){const s=learningSummary(meta()),now=new Date(),first=new Date(now.getFullYear(),now.getMonth(),1),count=new Date(now.getFullYear(),now.getMonth()+1,0).getDate(),days=new Set(s.days);return pageHeader('내 기록','한 걸음씩 쌓이는 한국사')+'<section class="v2-record-overview"><span>누적 문제 정답률</span><strong>'+percentText(s.accuracy)+'</strong><p>'+s.correct+'회 정답 / '+s.attempts+'회 풀이 · 실제 학습 기록</p></section>'+v2Metrics([['▤',s.attempts,'누적 풀이'],['◎',percentText(s.todayAccuracy),'오늘 정답률'],['▣',s.officialAttempts,'실제 기출 풀이'],['▧',meta().completedChapters.length,'완료 챕터']])+'<section class="v2-section"><h2>오늘의 학습</h2><p>'+s.todayAttempts+'문제 · '+s.streak+'일 연속 학습</p></section><section class="v2-section"><div class="section-title"><h2>학습 캘린더</h2><span>'+now.getFullYear()+'년 '+(now.getMonth()+1)+'월</span></div><div class="v2-calendar">'+['일','월','화','수','목','금','토'].map(d=>'<small>'+d+'</small>').join('')+'<span style="grid-column:span '+first.getDay()+'" '+(!first.getDay()?'hidden':'')+'></span>'+Array.from({length:count},(_,i)=>{const date=new Date(now.getFullYear(),now.getMonth(),i+1),active=days.has(learningDay(date));return '<span class="'+(active?'studied ':'')+(i+1===now.getDate()?'today':'')+'" aria-label="'+(i+1)+'일'+(active?' 학습함':'')+'">'+(i+1)+'</span>'}).join('')+'</div><p class="muted">날짜별 기록은 V2 이후 풀이부터 표시됩니다. 기존 누적 기록은 유지됩니다.</p></section>'+weakConcepts()+'<section class="v2-section"><h2>시대별 성적과 진행</h2>'+ERAS.map(([name],i)=>'<div class="v2-era-score"><b>'+esc(name)+'</b><span>'+(i?'준비중':percentText(s.accuracy))+'</span><div class="progress"><span style="width:'+(i?0:overallProgress())+'%"></span></div></div>').join('')+'</section>'+recordsBeforeV2().replace(/<header[\s\S]*?<\/header>/,'')};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.wrongFilter){e.stopImmediatePropagation();wrongFilter=b.dataset.wrongFilter;studyTab='review';render()}else if(b.dataset.weak){e.stopImmediatePropagation();wrongConcept=b.dataset.weak;studyTab='review';screen='study';render();window.scrollTo(0,0)}else if(b.dataset.studyJump){e.stopImmediatePropagation();studyTab=b.dataset.studyJump;screen='study';render();window.scrollTo(0,0)}else if(b.dataset.storyMemory){e.stopImmediatePropagation();const q=QUESTIONS.find(q=>q.questionId===b.dataset.storyMemory),s=STORIES[q?.relatedSceneId];if(s){const entries=conversationEntries(s,null);modal={type:'v2-memory',questionId:q.questionId};render()}}},true);
document.addEventListener('change',e=>{if(e.target.matches('[data-wrong-chapter]')){wrongChapter=e.target.value;render()}if(e.target.matches('[data-wrong-concept]')){wrongConcept=e.target.value;render()}});
const modalBeforeV2=modalHTML;
modalHTML=function(){if(modal?.type==='v2-memory'){const q=QUESTIONS.find(q=>q.questionId===modal.questionId),s=STORIES[q.relatedSceneId];return '<div class="modal-overlay"><section class="modal v2-memory-modal" role="dialog" aria-modal="true" aria-label="관련 스토리 다시 보기"><header><h2>'+esc(s.title||ASSETS[s.illustrationId]?.label||'관련 스토리')+'</h2><button data-action="close">닫기</button></header><img src="'+esc(ASSETS[s.illustrationId]?.src||'')+'" alt="실제 스토리 장면">'+conversationEntries(s,null).map(entry=>'<p><b>'+esc(entry.characterName||'')+'</b><br>'+esc(entry.dialogue||'')+'</p>').join('')+'</section></div>'}return modalBeforeV2()};
render();
